html, body {
  margin: 0; width: 1920px; height: 1080px; overflow: hidden;
  background: #000; color: #fff;
  font-family: "SamsungOne", "Noto Sans CJK SC", sans-serif;
}

/* 切换时挡住上一条残留最后一帧的黑幕，平时沉在视频下面。竖屏视频两侧就是纯黑 —— 用户要求：
 * 之前那层封面拉伸出来的模糊彩色背景抢注意力（2026-09-29）。 */
#mask { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; background: #000; }

video {
  position: absolute; left: 0; top: 0; width: 1920px; height: 1080px;
  object-fit: contain; background: transparent;
}

/* 切换瞬间盖在视频上的封面，出画面就撤。 */
/* 切换时盖在视频区域上的封面：透明底（两侧露出背景画布），.img 由 app.js 摆到视频将要占的
 * 那块区域、cover 裁切。**切换时画面上不许有 CSS 滤镜**：一层 blur(40px) 实测让每次切换多一秒多，见 CLAUDE.md。 */
#cover { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; overflow: hidden; display: none; }
#cover.show { display: block; }
#cover .img { position: absolute; background: center / cover no-repeat; will-change: transform; }
/* "early" 切换：整层（黑底 + 封面）一起滑进来，滑到位就盖住旧视频停住的最后一帧。 */
#cover.solid { background: #000; }

/* 切换中：背景画布提到视频上面，挡住上一条残留的最后一帧；封面在它上面。第一帧上屏后放下。 */
video { z-index: 0; }
#mask.over { z-index: 1; }
#cover { z-index: 1; }
/* **盖在视频上的这两层不许完全不透明**（0.99，底下的视频透出 1%，看不出来）。硬件视频层的位置尺寸是合成器
 * 画视频那一层时送给播放器的；被完全不透明的层盖住，合成器按遮挡把这一层跳过，新框一直没送 —— 撤封面那一刻
 * 才送、播放器再异步应用，新视频头几帧按上一条的框画：竖屏的拉满全屏、横屏的挤成竖条（用户：「横竖切换抖
 * 一下」）。只把改框提前到 seek 那一刻，用户看还是抖；加上 0.99，用户看不抖了（2026-09-30）。 */
#cover, #mask { opacity: 0.99; }

/* 登录框：官网的 login_page。放在屏幕内、完全透明、压在我们的登录界面下面 —— 挪到屏幕
 * 外的跨域框会被 Chromium 节流（定时器、渲染降频），拖慢官网出码。要有真实尺寸，
 * login.js 按二维码图片的大小认它。 */
iframe.login-frame { position: absolute; left: 0; top: 0; width: 1280px; height: 800px; border: 0; opacity: 0; pointer-events: none; z-index: 1; }

/* 桥接框：必须在文档里才加载，但观众不该看见它。 */
iframe.bridge { position: absolute; left: 0; top: 0; width: 1px; height: 1px; border: 0; opacity: 0; pointer-events: none; }

/* 作者、标题那层在右下角、居右（用户要求，2026-09-30）。 */
#info {
  position: absolute; right: 80px; bottom: 70px; width: 900px; text-align: right;
  text-shadow: 0 2px 6px rgba(0, 0, 0, 0.8);
  opacity: 0; transition: opacity 0.4s;
}
#info.show { opacity: 1; }
/* 暂停时下键选中作者：名字变成一块红底（再按确认进主页）。padding 用负的 margin-right 抵掉，没选中时文字照旧贴右边。 */
#author {
  display: inline-block; font-size: 38px; font-weight: bold; margin: 0 -22px 14px 0; padding: 6px 22px;
  border-radius: 40px; transition: background-color 0.15s;
}
#author.focus { background: #fe2c55; text-shadow: none; }
#desc {
  font-size: 30px; line-height: 1.45; max-height: 3em; overflow: hidden;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical;
}
/* 数字那一排（赞 · 收藏 · 评论 · 合集）。暂停时下键选中，选中的那个变红底块，和作者名字一样；负的 margin-right 抵掉最后一块的 padding。
 * 赞过的心是红的、收过的星是黄的；等服务器回的时候半透明。 */
#stats { font-size: 26px; margin: 14px -16px 0 0; }
#stats .act { display: inline-block; margin-left: 10px; padding: 5px 16px; border-radius: 30px; opacity: 0.85; transition: background-color 0.15s; }
#stats .act.lit { color: #fe2c55; opacity: 1; }
#stats #act-collect.lit { color: #ffc300; }
#stats .act.focus { background: #fe2c55; color: #fff; opacity: 1; text-shadow: none; }
#stats .act.busy { opacity: 0.45; }
#time { font-size: 24px; margin-top: 8px; opacity: 0.7; }
#hint { font-size: 24px; margin-top: 10px; opacity: 0.75; }

/* 进度条只在暂停时出来（用户要求：播放时底部一条进度是打扰）。 */
#progress { position: absolute; left: 0; right: 0; bottom: 0; height: 6px; background: rgba(255, 255, 255, 0.15); display: none; }
#progress.show { display: block; }
#bar { height: 100%; width: 0; background: #fe2c55; }

#paused {
  position: absolute; left: 50%; top: 50%; width: 160px; height: 160px; margin: -80px 0 0 -80px;
  border-radius: 80px; background: rgba(0, 0, 0, 0.45);
  font-size: 64px; line-height: 160px; text-align: center; letter-spacing: -8px;
  display: none;
}
#paused.show { display: block; }

/* z-index：切换时的封面层是 1，转圈要在它上面（老视频第一段能取十几秒，那段时间观众看到的是封面）。 */
#loading { position: absolute; left: 50%; top: 50%; margin: -40px 0 0 -100px; width: 200px; text-align: center; display: none; z-index: 3; }
#loading.show { display: block; }
#loading .dot { display: inline-block; width: 26px; height: 26px; border-radius: 13px; margin: 0 4px; animation: bob 0.9s infinite alternate; }
#loading .a { background: #25f4ee; }
#loading .b { background: #fe2c55; animation-delay: 0.45s; }
#loading .label { margin-top: 18px; font-size: 26px; opacity: 0.8; }
@keyframes bob { from { transform: translateY(-8px); } to { transform: translateY(8px); } }

#toast {
  z-index: 10;
  position: absolute; left: 50%; top: 80px; transform: translateX(-50%);
  padding: 18px 40px; border-radius: 40px; background: rgba(0, 0, 0, 0.7);
  font-size: 30px; opacity: 0; transition: opacity 0.3s;
}
#toast.show { opacity: 1; }

/* 顶部标签栏：和信息层一起出现、一起淡出；非视频页上常驻。 */
#tabs {
  position: absolute; left: 0; right: 0; top: 36px; text-align: center; z-index: 5;
  opacity: 0; transition: opacity 0.4s; text-shadow: 0 2px 6px rgba(0, 0, 0, 0.8);
}
#tabs.show { opacity: 1; }
#tabs .tab { display: inline-block; margin: 0 34px; font-size: 34px; color: rgba(255, 255, 255, 0.6); padding-bottom: 8px; }
#tabs .tab.on { color: #fff; font-weight: bold; border-bottom: 5px solid #fff; }
#tabs .tab-hint { font-size: 24px; opacity: 0.6; }

/* 登录 / 空页：盖在视频层上的整屏面板。 */
#login, #empty {
  position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; background: #161823;
  text-align: center; display: none; z-index: 2;
}
#login.show, #empty.show { display: block; }
#login-title { margin-top: 170px; font-size: 44px; font-weight: bold; }
.qr-box { width: 440px; height: 440px; margin: 50px auto 0; background: #fff; border-radius: 20px; padding: 20px; box-sizing: border-box; }
#qr { width: 400px; height: 400px; image-rendering: pixelated; visibility: hidden; }
#login-msg { margin-top: 40px; font-size: 32px; min-height: 44px; }
#empty-msg { margin-top: 440px; font-size: 38px; }
/* 没登录时「我」的二维码页最底下那一排：诊断日志（js/diag.js），和「我」页顶上那一排一个样子。 */
#login-diag { position: absolute; left: 0; right: 0; bottom: 110px; font-size: 28px; display: none; }
#login-diag.show { display: block; }
#login-diag .t { display: inline-block; margin: 0 13px; padding: 6px 24px; border-radius: 34px; opacity: 0.55; }
#login-diag .t.focus { background: #fe2c55; opacity: 1; }
#login-diag-msg { position: absolute; left: 160px; right: 160px; bottom: 50px; font-size: 24px; opacity: 0.6; }

/* 网格页：作者主页、「我」、选集（js/grid.js 按这里的尺寸摆卡片：4 列 398×531（3:4）、间距 36、左边 110、网格从 300 开始，
 * 「我」从 380 开始）。
 * 整屏不透明面板，停着的视频在下面。翻页只动 #gp-scroll 的 transform；**不许加滤镜**（见 CLAUDE.md）。 */
#grid-page { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; background: #161823; overflow: hidden; display: none; z-index: 2; }
#grid-page.show { display: block; }
#gp-scroll { position: absolute; left: 0; top: 0; width: 1920px; transition: transform 250ms cubic-bezier(0.2, 0.8, 0.2, 1); }
#gp-avatar { position: absolute; left: 110px; top: 70px; width: 160px; height: 160px; border-radius: 80px; object-fit: cover; background: #2a2c38; }
#gp-name { position: absolute; left: 310px; top: 76px; font-size: 52px; font-weight: bold; }
#gp-stats { position: absolute; left: 310px; top: 150px; font-size: 28px; opacity: 0.85; }
#gp-sign {
  position: absolute; left: 310px; top: 198px; width: 1400px; font-size: 24px; line-height: 1.4; opacity: 0.6;
  white-space: pre-line; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
}
#gp-foot { position: absolute; left: 110px; width: 1700px; text-align: center; font-size: 26px; opacity: 0.6; }
#gp-grid .card {
  position: absolute; width: 398px; height: 531px; border-radius: 14px; overflow: hidden; background: #2a2c38;
  transition: transform 150ms;
}
#gp-grid .card.on { transform: scale(1.05); box-shadow: 0 0 0 6px #fff; z-index: 1; }
/* 自测 --grid 轮换的做法（Author.setMode）："layer" 让整块网格常驻一个合成层（不在每次滚动时提起、滚完放下、
 * 整屏重新光栅化）；"snap" 焦点卡片放大不做过渡（过渡期间那张卡片会被临时提成一个层）。 */
#gp-scroll.layer { will-change: transform; }
#gp-grid.snap .card { transition: none; }
#gp-grid .card img { width: 100%; height: 100%; object-fit: cover; display: block; }
#gp-grid .shade { position: absolute; left: 0; right: 0; bottom: 0; height: 50%; background: linear-gradient(rgba(0, 0, 0, 0), rgba(0, 0, 0, 0.8)); }
#gp-grid .d {
  position: absolute; left: 18px; right: 18px; bottom: 54px; font-size: 25px; line-height: 1.35; max-height: 2.7em; overflow: hidden;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical;
}
#gp-grid .l { position: absolute; left: 18px; bottom: 16px; font-size: 24px; opacity: 0.9; }
#gp-grid .pin { position: absolute; left: 12px; top: 12px; padding: 3px 12px; border-radius: 6px; background: #fe2c55; font-size: 22px; }
.hint { margin-top: 30px; font-size: 24px; opacity: 0.5; }

/* 「我」：顶上有标签栏（它是一个标签），头部往下挪；头部下面一排观看历史 · 喜欢 · 收藏 · 退出登录，焦点在这一排时那一项是红底块。 */
#grid-page.me #gp-avatar { top: 120px; width: 130px; height: 130px; border-radius: 65px; }
#grid-page.me #gp-name { left: 280px; top: 128px; font-size: 44px; }
#grid-page.me #gp-stats { left: 280px; top: 194px; }
#gp-tabs { position: absolute; left: 110px; top: 290px; width: 1700px; overflow: hidden; font-size: 32px; }
#gp-tabs .in { white-space: nowrap; transition: transform 200ms; }
#gp-tabs .t { display: inline-block; margin-right: 26px; padding: 6px 24px; border-radius: 34px; opacity: 0.55; }
#gp-tabs .t.on { opacity: 1; font-weight: bold; }
#gp-tabs .t.focus { background: #fe2c55; }
/* 选集：头像那块放合集的封面，方的。 */
#grid-page.mix #gp-avatar { border-radius: 12px; }

/* 评论侧栏（js/comments.js）：盖在画面右边，视频停在左边。列表只动 #cm-list 的 transform，常驻一个合成层（作者主页网格
 * 量过：不常驻的话每滚一次都整块重新光栅化）。 */
#comments { position: absolute; right: 0; top: 0; width: 820px; height: 1080px; background: rgba(22, 24, 35, 0.96); z-index: 4; display: none; }
#comments.show { display: block; }
#cm-title { position: absolute; left: 50px; top: 46px; font-size: 34px; font-weight: bold; }
#cm-view { position: absolute; left: 0; right: 0; top: 120px; height: 900px; overflow: hidden; }
#cm-list { position: absolute; left: 0; right: 0; top: 0; will-change: transform; transition: transform 200ms cubic-bezier(0.2, 0.8, 0.2, 1); }
#cm-hint { position: absolute; left: 50px; bottom: 22px; font-size: 22px; opacity: 0.5; }
#cm-list .cm { position: relative; margin: 0 30px; padding: 16px 20px 16px 86px; border-radius: 16px; min-height: 60px; }
#cm-list .cm.reply { margin-left: 100px; padding-left: 70px; }
#cm-list .cm.on, #cm-list .cm-more.on { background: rgba(255, 255, 255, 0.12); }
#cm-list .av { position: absolute; left: 18px; top: 18px; width: 52px; height: 52px; border-radius: 26px; object-fit: cover; background: #2a2c38; }
#cm-list .cm.reply .av { width: 40px; height: 40px; border-radius: 20px; }
#cm-list .nm { font-size: 23px; opacity: 0.6; }
#cm-list .tx { font-size: 28px; line-height: 1.4; margin-top: 4px; word-wrap: break-word; }
#cm-list .mt { font-size: 21px; opacity: 0.45; margin-top: 6px; }
#cm-list .rp { font-size: 22px; color: #9ab3ff; margin-top: 6px; }
#cm-list .rp:empty { display: none; }
#cm-list .cm-more { margin: 0 30px 0 100px; padding: 12px 20px; border-radius: 16px; font-size: 22px; color: #9ab3ff; }
#cm-list .cm-foot { padding: 24px 0 40px; text-align: center; font-size: 24px; opacity: 0.5; }

files.js/diag.js:
/* 诊断日志：别人电视上的问题传回给开发者（2026-10-21，照搬 bilibili-tizen 的 diag.js）。
 *
 * 8098 上的收集器（tools/collect.mjs）只有开发构建有。装了发布包的电视出了事，开发者这边一个字都看不到，
 * 能拿到的只有一张提示框的照片 —— bilibili 那边 issue #5 就是这样：一台 Tizen 3.0 每个视频都 403，
 * 屏幕上说不出是哪条路被哪台主机拒了。
 *
 * 所以每一行日志同时记进这里的一圈（记的时候就去掉身份），出了观众看得见的事（Diag.incident）、或者观众在
 * 「我」里按「上传诊断日志」时，把这一圈传上去。默认开，「我」里能关；关了就什么都不记、不存、不传。
 *
 * 永远不离开电视的：账号的 uid / sec_uid、昵称、作者名、视频文案、登录页上的字、设备指纹（webid、verifyFp、
 * msToken、a_bogus……）。调用处把前几样包进 Diag.priv()，上传时换成「…」；scrub() 里的规则兜住容易忘的形状
 * （url 参数、cookie 值、sec_uid 的样子）。视频 id 留着：「只有这一条放不了」没有它就复现不了。
 *
 * 接收端是 bilibili-tizen 的 server/diag-worker.mjs（两个应用共用，按 app 分开），读用那边的
 * tools/diag-logs.mjs --app douyin-tizen。这个文件随每个更新包下发，所以接收地址和去隐私的规则都能靠更新修；
 * config.js 不随更新下发，所以地址写在这里。ES5，和 app/js 里的一切一样。 */
var Diag = (function () {
    "use strict";

    var ENDPOINT = "https://diag.titdev.nl/v1/upload";   /* bilibili-tizen/server/README.md */
    var APP = "douyin-tizen";

    var K_RING = "dy.diag.ring", K_DEVICE = "dy.diag.device", K_SENT = "dy.diag.sent", K_OFF = "dy.diag.off";

    /* 600 行大约是一条视频从起播到放弃的全部，加上之前那次启动；字数上限让 localStorage 占用在 300KB 上下
     * （UTF-16），和同一份配额里的更新包（约 490KB）、推荐缓存都离得远。 */
    var MAX_LINES = 600, MAX_CHARS = 160000, MAX_LINE = 4000;
    var SETTLE = 8000;          /* 出事之后等一会儿，让解释它的那几行（重试、换路）也进来 */
    var AUTO_GAP = 180000;      /* 自动上传最多三分钟一份…… */
    var AUTO_PER_DAY = 12;      /* ……一天十二份：卡在循环里的电视不能变成水龙头 */
    var MANUAL_GAP = 10000;
    var PERSIST_EVERY = 15000;

    var OPEN = "\uE000", CLOSE = "\uE001";   /* 私用区的两个字符：日志里不会自然出现 */

    var report = function () {};
    var ring = [], chars = 0, loaded = false;
    var persistTimer = null, settleTimer = null, reasons = [], sending = false;
    var last = null;            /* {at, ok, id, why, manual} —— 这次启动最近一次上传，「我」里那行字用 */

    function get(k) { try { return localStorage.getItem(k); } catch (e) { return null; } }
    function put(k, v) { try { localStorage.setItem(k, v); return true; } catch (e) { return false; } }
    function del(k) { try { localStorage.removeItem(k); } catch (e) {} }
    function parse(s) { try { return s ? JSON.parse(s) : null; } catch (e) { return null; } }
    function now() { return new Date().getTime(); }

    /* 这里没有 settings.js（属于这台电视的设置只有这一个），开关直接记在 localStorage。 */
    function enabled() { return get(K_OFF) !== "1"; }

    /* 开发构建（REPORT_TO 非空，自测构建也是）有收集器，什么都不传 —— 除非 deploy.sh 给了地址
     * （DOUYIN_DIAG_TO → config.js 的 DIAG_TO），在电视上测上传这条路就靠它。比这个文件老的安装包里，
     * config.js 没有 DIAG_TO，所以用 typeof。 */
    function endpoint() {
        var override = typeof DIAG_TO !== "undefined" ? DIAG_TO : "";
        if (override) { return override; }
        var dev = typeof REPORT_TO !== "undefined" && !!REPORT_TO;
        return dev ? "" : ENDPOINT;
    }

    /* ---------------- 什么能传出去 ---------------- */

    function priv(s) {
        return OPEN + String(s == null ? "" : s).replace(/[\uE000\uE001]/g, "") + CLOSE;
    }
    function plain(s) { return String(s == null ? "" : s).replace(/[\uE000\uE001]/g, ""); }

    var NET = [
        /* 调用处包起来的。没合上的一段算到行尾：slice() 切掉了结尾的记号，也不能把后面漏出去。 */
        [/\uE000[^\uE001]*(?:\uE001|$)/g, "…"],
        [/[\uE000\uE001]/g, ""],
        /* 账号：sec_uid 有固定的开头（MS4wLjABAAAA，base64 的 protobuf 头），uid 是一串数字。 */
        [/MS4wLjABAAAA[\w-]+/g, "…"],
        [/\b((?:sec_uid|sec_user_id|user_id|uid|author_id|nickname|unique_id|short_id) ?[=:：] ?)[^\s&|；;，,）)"']+/g, "$1…"],
        /* 签名和设备指纹参数，任何进了日志的 url 里都去掉。 */
        [/([?&](?:a_bogus|X-Bogus|msToken|verifyFp|fp|webid|uifid|device_id|iid|ttwid|s_v_web_id|passport_csrf_token|sessionid|sid_tt|sid_guard|uid_tt|odin_tt|ticket|csrf_token)=)[^&\s"'<>]*/g, "$1…"],
        /* cookie 的值（名字留着：account 那行报「框里可见的 cookie」只报名字，判登录态要它）。 */
        [/\b(ttwid|s_v_web_id|sessionid|sessionid_ss|sid_tt|sid_guard|uid_tt|odin_tt|passport_csrf_token|passport_assist_user|msToken|UIFID|UIFID_TEMP|__ac_nonce|__ac_signature|bd_ticket_guard_client_data|_bd_ticket_crypt_cookie)=[^;&\s]+/g, "$1=…"],
        /* 32 位以上的十六进制串：令牌、指纹，读日志的人用不上。 */
        [/\b[0-9a-f]{32,}\b/g, "…"]
    ];

    function scrub(s) {
        var out = String(s == null ? "" : s);
        for (var i = 0; i < NET.length; i++) { out = out.replace(NET[i][0], NET[i][1]); }
        return out;
    }

    /* ---------------- 那一圈 ---------------- */

    function pad(n) { return n < 10 ? "0" + n : String(n); }
    function stamp() {
        var d = new Date();
        return pad(d.getMonth() + 1) + "-" + pad(d.getDate()) + " " +
               pad(d.getHours()) + ":" + pad(d.getMinutes()) + ":" + pad(d.getSeconds());
    }

    function load() {
        if (loaded) { return; }
        loaded = true;
        var kept = parse(get(K_RING));
        if (kept && kept.length) {
            ring = kept.slice(-MAX_LINES);
            for (var i = 0; i < ring.length; i++) { chars += String(ring[i]).length; }
        }
    }

    function persist() {
        if (persistTimer) { clearTimeout(persistTimer); persistTimer = null; }
        if (!enabled()) { return; }
        put(K_RING, JSON.stringify(ring));
    }

    function push(line) {
        load();
        if (line.length > MAX_LINE) { line = line.slice(0, MAX_LINE) + "…（这一行太长，截在 " + MAX_LINE + " 字）"; }
        ring.push(line);
        chars += line.length;
        while (ring.length > 1 && (ring.length > MAX_LINES || chars > MAX_CHARS)) { chars -= ring.shift().length; }
        if (!persistTimer) { persistTimer = setTimeout(persist, PERSIST_EVERY); }
    }

    function record(kind, detail) {
        if (!enabled()) { return; }
        try { push(stamp() + " " + scrub(kind + ": " + detail)); } catch (e) {}
    }

    /* ---------------- 上传 ---------------- */

    var ALPHABET = "ABCDEFGHJKMNPQRSTVWXYZ23456789";   /* 没有 0/O、1/I/L、U：要从屏幕上念出来 */
    function deviceId() {
        var id = get(K_DEVICE);
        if (id && /^[A-Z2-9]{8}$/.test(id)) { return id; }
        id = "";
        var bytes = null;
        try { bytes = new Uint8Array(8); window.crypto.getRandomValues(bytes); } catch (e) { bytes = null; }
        for (var i = 0; i < 8; i++) {
            var r = bytes ? bytes[i] : Math.floor(Math.random() * 256);
            id += ALPHABET.charAt(r % ALPHABET.length);
        }
        put(K_DEVICE, id);
        return id;
    }
    function shown(id) { return id.slice(0, 4) + "-" + id.slice(4); }

    function today() {
        var d = new Date();
        return d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate());
    }
    function sentState() {
        var s = parse(get(K_SENT)) || {};
        if (s.day !== today()) { s = { day: today(), n: 0, at: 0, manualAt: s.manualAt || 0 }; }
        return s;
    }

    function post(url, body, cb) {
        var finished = false;
        function end(status, text) { if (!finished) { finished = true; cb(status, text); } }
        try {
            var xhr = new XMLHttpRequest();
            xhr.open("POST", url, true);
            /* text/plain 让它是个简单请求：会发预检的引擎上也不发。 */
            xhr.setRequestHeader("Content-Type", "text/plain;charset=UTF-8");
            xhr.timeout = 20000;
            xhr.onreadystatechange = function () {
                if (xhr.readyState === 4) { end(xhr.status, xhr.responseText); }
            };
            xhr.ontimeout = function () { end(0, "超时"); };
            xhr.onerror = function () { end(0, "连不上"); };
            xhr.send(body);
        } catch (e) { end(0, "发不出去：" + (e && e.message)); }
    }

    function versions() {
        try { return Boot.info(); } catch (e) { return { packaged: "", running: "" }; }
    }

    /* reason：为什么传这一份，用观众看到的那句话。 */
    function send(reason, manual, done) {
        done = done || function () {};
        /* 手动按的要在「我」那行字里有个回答，所以每一种结局 —— 包括这里就拒了的 —— 都记进 last。 */
        function refuse(why) {
            if (manual) { last = { at: now(), ok: false, why: why, manual: true }; }
            done({ ok: false, why: why });
        }
        if (!enabled()) { refuse("诊断日志关着"); return; }
        var url = endpoint();
        if (!url) { refuse("这个版本没有接收地址"); return; }
        if (sending) { refuse("正在上传上一份"); return; }
        var t = now(), s = sentState();
        if (manual) {
            if (t - (s.manualAt || 0) < MANUAL_GAP) { refuse("刚传过，过几秒再按"); return; }
            s.manualAt = t;
        } else {
            if (t - (s.at || 0) < AUTO_GAP) {
                report("diag", "没传（三分钟内自动传过一份）：" + reason);
                done({ ok: false, why: "三分钟内传过" });
                return;
            }
            if (s.n >= AUTO_PER_DAY) {
                report("diag", "没传（今天已经自动传了 " + s.n + " 份）：" + reason);
                done({ ok: false, why: "今天传够了" });
                return;
            }
            s.n++;
            s.at = t;
        }
        put(K_SENT, JSON.stringify(s));

        load();
        var v = versions();
        var body = JSON.stringify({
            v: 1, app: APP, device: deviceId(),
            version: v.packaged || "", running: v.running || "",
            reason: scrub(reason).slice(0, 300), manual: !!manual,
            tvAt: t, tz: new Date().getTimezoneOffset(),
            ua: String(navigator.userAgent || "").slice(0, 300),
            lines: ring.slice()
        });
        persist();
        sending = true;
        var lines = ring.length;
        post(url, body, function (status, text) {
            /* 老电视的根证书未必认得接收端的证书，而最需要诊断的恰恰是老电视。https 在网络层失败就用 http
             * 再试一次，日志里写走的是哪条 —— 只有这样才知道这条退路到底用不用得上。 */
            if (status === 0 && /^https:/.test(url)) {
                post("http:" + url.slice(6), body, function (s2, t2) { finish(s2, t2, "http（https " + text + "）"); });
                return;
            }
            finish(status, text, /^https:/.test(url) ? "https" : "http");
        });
        function finish(status, text, via) {
            sending = false;
            var res = parse(text) || {};
            if (status >= 200 && status < 300 && res.id) {
                last = { at: now(), ok: true, id: res.id, manual: !!manual };
                report("diag", "传了 " + lines + " 行，编号 " + res.id + "，走 " + via + "（" + reason + "）");
                done({ ok: true, id: res.id });
            } else {
                var why = status ? "HTTP " + status + (res.error ? " " + res.error : "") : String(text || "连不上");
                last = { at: now(), ok: false, why: why, manual: !!manual };
                report("diag", "没传上：" + why + "，走 " + via + "（" + reason + "）");
                done({ ok: false, why: why });
            }
        }
    }

    function incident(reason) {
        if (!enabled() || !endpoint()) { return; }
        reasons.push(String(reason || "?").slice(0, 120));
        if (settleTimer) { return; }
        settleTimer = setTimeout(function () {
            settleTimer = null;
            var why = reasons.join(" / ");
            reasons = [];
            send(why, false);
        }, SETTLE);
    }

    if (typeof document !== "undefined" && document.addEventListener) {
        /* Tizen 多半是挂起而不是杀进程；藏起来的页面可能再也跑不到那个 15 秒的定时器。 */
        try {
            document.addEventListener("visibilitychange", function () {
                if (document.hidden) { persist(); }
            });
            window.addEventListener("pagehide", persist);
        } catch (e) {}
    }

    return {
        priv: priv,
        plain: plain,
        scrub: scrub,
        record: record,
        incident: incident,
        /* app.js 的 window.onload 里调：日志通道，再记一行分界，留下来的那一圈看得出哪次启动从哪开始。 */
        init: function (opts) {
            if (opts && opts.report) { report = opts.report; }
            if (enabled()) { push(stamp() + " diag: —— 新的一次启动 ——"); }
        },
        upload: function (done) { send("在「我」里手动上传", true, done); },
        enabled: enabled,
        setEnabled: function (on) {
            if (on) { del(K_OFF); return; }
            put(K_OFF, "1");
            ring = []; chars = 0; reasons = [];
            if (settleTimer) { clearTimeout(settleTimer); settleTimer = null; }
            if (persistTimer) { clearTimeout(persistTimer); persistTimer = null; }
            del(K_RING);
        },
        status: function () {
            return { enabled: enabled(), configured: !!endpoint(), device: shown(deviceId()),
                     lines: (load(), ring.length), sending: sending || !!settleTimer, last: last };
        },
        _test: { NET: NET, endpoint: endpoint, ring: function () { return ring.slice(); },
                 SETTLE: SETTLE, AUTO_GAP: AUTO_GAP, AUTO_PER_DAY: AUTO_PER_DAY }
    };
})();

