            return {kind: cur.kind, name: cur.title, cards: cur.cards.length, imgs: imgs, sel: cur.sel, zone: cur.zone, tab: key(cur),
                    stats: $("gp-stats").textContent, avatar: $("gp-avatar").naturalWidth || 0, foot: $("gp-foot").textContent};
        }
    };
})();

