            return (e.info ? "开头已转好、还在 append" : "还没拿到 moov") + "，" + (e.xhr ? "请求在途 " + ((Date.now() - e.xhrAt) / 1000).toFixed(1) + "s，收到 " +
                   mb(e.xhrGot || 0) + "/" + mb(e.xhrWant) + (e.xhrHost ? "，" + e.xhrHost : "，还没有响应") : "没有请求在途") + "，已取 " + mb(e.next);
        },
