    function waitFor(fn, ms) {
        var t0 = Date.now();
        function poll() {
            var v = false;
            try { v = fn(); } catch (e) {}
            if (v) { return Promise.resolve(Date.now() - t0); }
            if (Date.now() - t0 > ms) { return Promise.resolve(-1); }
            return wait(250).then(poll);
        }
        return poll();
    }
